SELECT * FROM leetcode_recommend_feedback 
WHERE student_id = #{studentId}
ORDER BY action_at DESC

    LIMIT #{limit}

SELECT * FROM leetcode_recommend_feedback 
WHERE request_id = #{requestId}
ORDER BY action_at ASC

SELECT * FROM leetcode_recommend_feedback 
WHERE problem_id = #{problemId}
ORDER BY action_at DESC

    LIMIT #{limit}

SELECT action, COUNT(*) as actionCount, COUNT(DISTINCT problem_id) as uniqueProblems, COUNT(DISTINCT request_id) as uniqueRequests FROM leetcode_recommend_feedback WHERE student_id = #{studentId}
AND action_at >= DATE_SUB(NOW(), INTERVAL #{days} DAY)
GROUP BY action ORDER BY actionCount DESC
